BEGIN;
DO $$
DECLARE w uuid:=gen_random_uuid(); foreign_w uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); l public.looks; op public.workflow_operations; done public.workflow_operations; ev public.workflow_operation_events; item uuid:=gen_random_uuid(); piece uuid:=gen_random_uuid(); n integer;
BEGIN
 INSERT INTO public.workspaces(id,name) VALUES(w,'__owner2_smoke_'||w),(foreign_w,'__owner2_foreign_'||foreign_w);
 INSERT INTO public.user_preferences(workspace_id) VALUES(w);
 INSERT INTO public.assets(id,workspace_id,bucket,storage_path,mime_type,byte_size,source_type) VALUES(a,w,'inspiration',w::text||'/'||a::text||'/fixture.jpg','image/jpeg',1,'sample');
 INSERT INTO public.workflow_drafts(id,workspace_id,feature_kind) VALUES(d,w,'inspiration');
 BEGIN PERFORM public.attach_inspiration_upload(foreign_w,a,d,1,NULL); RAISE EXCEPTION 'foreign workspace accepted'; EXCEPTION WHEN no_data_found THEN NULL; END;
 l:=public.attach_inspiration_upload(w,a,d,1,'smart casual');
 BEGIN PERFORM public.attach_inspiration_upload(w,a,d,1,NULL); RAISE EXCEPTION 'stale draft accepted'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 l:=public.save_inspiration_pieces(w,l.id,l.revision,jsonb_build_array(jsonb_build_object('id',piece,'name','Synthetic top','category','top','position',0)));
 op:=public.start_workflow_operation(w,'inspiration_description','look',l.id,l.revision,repeat('c',64),jsonb_build_object('lookId',l.id,'lookRevision',l.revision));
 op:=public.claim_workflow_operation(w,op.id,l.revision);
 ev:=public.append_create_event(w,op.id,op.attempt_count,'started','{}');
 IF ev.sequence<>1 THEN RAISE EXCEPTION 'event sequence invalid'; END IF;
 BEGIN PERFORM public.finish_create_operation(w,op.id,op.attempt_count+1,'{}','{}'); RAISE EXCEPTION 'stale attempt accepted'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 FOR n IN 1..3 LOOP PERFORM public.reserve_create_provider_call(w,op.id,op.attempt_count); PERFORM public.release_create_provider_call(w,op.id,op.attempt_count); END LOOP;
 BEGIN PERFORM public.reserve_create_provider_call(w,op.id,op.attempt_count); RAISE EXCEPTION 'request budget ignored'; EXCEPTION WHEN program_limit_exceeded THEN NULL; END;
 UPDATE public.looks SET revision=revision+1 WHERE workspace_id=w AND id=l.id;
 done:=public.finish_create_operation(w,op.id,op.attempt_count,'{}','{}');
 IF done.status<>'superseded' THEN RAISE EXCEPTION 'stale completion accepted'; END IF;
 SELECT * INTO l FROM public.looks WHERE workspace_id=w AND id=l.id;
 op:=public.start_workflow_operation(w,'inspiration_confidence','look',l.id,l.revision,repeat('d',64),jsonb_build_object('lookId',l.id,'lookRevision',l.revision,'preferenceData',jsonb_build_object('styleDna','{}'::jsonb,'fitPreferences','{}'::jsonb,'bodyProfile','{}'::jsonb)));
 op:=public.claim_workflow_operation(w,op.id,l.revision);
 UPDATE public.user_preferences SET style_dna='{"undertone":"cool"}',revision=revision+1 WHERE workspace_id=w;
 done:=public.finish_create_operation(w,op.id,op.attempt_count,'{}','{}');
 IF done.status<>'superseded' THEN RAISE EXCEPTION 'changed preferences accepted'; END IF;
 op:=public.start_workflow_operation(w,'wardrobe_match','look',l.id,l.revision,repeat('e',64),jsonb_build_object('lookId',l.id,'lookRevision',l.revision));
 done:=public.control_create_operation(w,op.id,'cancel');
 IF done.status<>'cancelled' OR NOT EXISTS(SELECT 1 FROM public.workflow_operation_events WHERE workspace_id=w AND operation_id=op.id AND event_type='cancelled') THEN RAISE EXCEPTION 'cancel was not replayable'; END IF;
 INSERT INTO public.wardrobe_items(id,workspace_id,name,category) VALUES(item,w,'Synthetic top','top');
 INSERT INTO public.wardrobe_matches(workspace_id,look_id,piece_id,wardrobe_item_id,match_type,rationale,source_revision) VALUES(w,l.id,piece,item,'owned_match','Synthetic test only.',l.revision);
 UPDATE public.wardrobe_items SET archived_at=clock_timestamp() WHERE workspace_id=w AND id=item;
 UPDATE public.wardrobe_matches SET is_current=false WHERE workspace_id=w AND look_id=l.id;
 IF has_function_privilege('anon','public.finish_create_operation(uuid,uuid,integer,jsonb,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.control_create_operation(uuid,uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'privileged RPC exposed'; END IF;
END; $$;
ROLLBACK;
SELECT 'owner2 transaction, fencing, preference invalidation, quota, cancellation and historical-match checks passed; fixtures rolled back' AS result;
